import{_ as t,o as r,c as a,a3 as s}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"What the server cleans up","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cleanup.md","filePath":"reference/cleanup.md"}'),d={name:"reference/cleanup.md"};function o(n,e,h,i,l,c){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="what-the-server-cleans-up" tabindex="-1">What the server cleans up <a class="header-anchor" href="#what-the-server-cleans-up" aria-label="Permalink to &quot;What the server cleans up&quot;">​</a></h1><p>The server deletes the records nobody can use any more by itself: one minute after it starts, then every hour. There is nothing to set up. With several server processes on one database, only one runs a pass at a time; the others skip theirs.</p><h2 id="what-a-pass-deletes" tabindex="-1">What a pass deletes <a class="header-anchor" href="#what-a-pass-deletes" aria-label="Permalink to &quot;What a pass deletes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Record</th><th>Deleted</th></tr></thead><tbody><tr><td>Sessions, OAuth access tokens</td><td>1 day after they expired or were revoked</td></tr><tr><td>Personal access tokens</td><td>30 days after they expired or were revoked; the <strong>Tokens</strong> screen lists them until then</td></tr><tr><td>OAuth authorization codes, refresh tokens</td><td>1 day after they expired, used or not</td></tr><tr><td>Device sign-in requests</td><td>1 hour after they expired</td></tr><tr><td>Registered OAuth clients without a grant</td><td>24 hours after registration</td></tr><tr><td>Workspace invitations</td><td>30 days after they expired, were used or were revoked</td></tr></tbody></table><p>The server also deletes its internal bookkeeping records, which no screen or command shows:</p><table tabindex="0"><thead><tr><th>Internal record</th><th>Deleted</th></tr></thead><tbody><tr><td>Idempotency keys</td><td>30 days after the command: a retry with the same key within 30 days returns the original result, later it runs as a new command</td></tr><tr><td>Outbox rows</td><td>1 day after they were published</td></tr><tr><td>Stream deliveries</td><td>When 1,000 or more behind the project&#39;s latest one, since a stream that far behind gets <code>reset</code> instead</td></tr></tbody></table><p>Events, audit entries, read models, OAuth grants and evidence are never deleted. A record exactly at its limit is kept.</p><h2 id="in-the-logs" tabindex="-1">In the logs <a class="header-anchor" href="#in-the-logs" aria-label="Permalink to &quot;In the logs&quot;">​</a></h2><p>Each pass deletes at most 1,000 rows per statement, so it never holds long locks. A pass that deleted something logs one <code>records cleaned</code> line with the count per record and its <code>durationMs</code>; a failed pass logs <code>cleanup failed</code>, and the next hour&#39;s pass tries again. See <a href="/wake-dist/docs/run/logs">Logs</a>.</p>',9)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
